/* From Uiverse.io by SharpTH - Tags: card */
.__UIV_SCOPE__ .card {
 cursor: pointer;
 width: 190px;
 height: 254px;
 background: rgb(255, 255, 255);
 border-radius: 5px;
 border: 1px solid rgba(0, 0, 255, .2);
 transition: all .2s;
 box-shadow: 12px 12px 2px 1px rgba(0, 0, 255, .2);
}

.__UIV_SCOPE__ .card:hover {
 box-shadow: -12px 12px 2px -1px rgba(0, 0, 255, .2);
}
